#!/usr/bin/env python3
"""Write the small SQL Logic Test fixture corpus next to this file.

The files are in the format of the public SQL Logic Test corpus. Expected values come from
SQLite (Python's sqlite3 module), for statements whose answer is the same in SQLite and
PostgreSQL. Where the two differ only in where NULL sorts, the file holds the plain
ORDER BY and SQLite is asked the same question with the PostgreSQL placement spelled out
(NULLS LAST ascending, NULLS FIRST descending).

Run: python3 tests/fixtures/slt/generate.py      (deterministic: fixed seed, no clock)
"""
import hashlib
import os
import random
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))
HASH_THRESHOLD = 8


def fmt(value, ty):
    if value is None:
        return "NULL"
    if ty == "I":
        return str(int(value))
    if ty == "R":
        return "%.3f" % float(value)
    text = str(value)
    if text == "":
        return "(empty)"
    return "".join(c if " " <= c <= "~" else "@" for c in text)


class Script:
    def __init__(self, name):
        self.name = name
        self.db = sqlite3.connect(":memory:")
        self.out = ["# Generated by tests/fixtures/slt/generate.py. Do not edit by hand.", "",
                    "hash-threshold %d" % HASH_THRESHOLD, ""]
        self.records = 0

    def ok(self, sql, prefix=None):
        self.db.execute(sql)
        if prefix:
            self.out.append(prefix)
        self.out += ["statement ok", sql, ""]
        self.records += 1

    def error(self, sql):
        try:
            self.db.execute(sql)
        except sqlite3.Error:
            pass
        else:
            raise SystemExit("expected an error from: " + sql)
        self.out += ["statement error", sql, ""]
        self.records += 1

    def foreign(self, prefix, kind, sql, expected=()):
        """A record for another engine only: SQLite is not asked, the answer is given."""
        self.out += [prefix, kind, sql]
        if kind.startswith("query"):
            self.out += ["----"] + list(expected)
        self.out.append("")
        self.records += 1

    def query(self, types, sql, sort="nosort", label=None, ask=None, prefix=None):
        rows = self.db.execute(ask or sql).fetchall()
        for row in rows:
            if len(row) != len(types):
                raise SystemExit("type string %s does not fit: %s" % (types, sql))
        rendered = [[fmt(v, t) for v, t in zip(row, types)] for row in rows]
        if sort == "rowsort":
            rendered.sort(key=lambda r: [c.encode() for c in r])
        values = [c for row in rendered for c in row]
        if sort == "valuesort":
            values.sort(key=lambda c: c.encode())
        head = "query %s %s" % (types, sort)
        if label:
            head += " " + label
        if prefix:
            self.out.append(prefix)
        self.out += [head, sql, "----"]
        if len(values) > HASH_THRESHOLD:
            digest = hashlib.md5("".join(v + "\n" for v in values).encode()).hexdigest()
            self.out.append("%d values hashing to %s" % (len(values), digest))
        else:
            self.out += values
        self.out.append("")
        self.records += 1

    def write(self):
        path = os.path.join(HERE, self.name)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            f.write("\n".join(self.out))
        return self.records


def seed_tables(s, rng, rows=24):
    s.ok("CREATE TABLE t1(a INTEGER PRIMARY KEY, b INTEGER, c INTEGER, d VARCHAR(20))")
    s.ok("CREATE TABLE t2(x INTEGER PRIMARY KEY, a INTEGER, y INTEGER, z VARCHAR(20))")
    words = ["alpha", "beta", "gamma", "delta", "", "omega"]
    for i in range(1, rows + 1):
        b = "NULL" if rng.random() < 0.2 else str(rng.randint(-20, 40))
        c = "NULL" if rng.random() < 0.15 else str(rng.randint(0, 9))
        d = "NULL" if rng.random() < 0.15 else "'%s'" % rng.choice(words)
        s.ok("INSERT INTO t1(a,b,c,d) VALUES(%d,%s,%s,%s)" % (i, b, c, d))
    for i in range(1, rows + 1):
        a = "NULL" if rng.random() < 0.15 else str(rng.randint(1, rows + 6))
        y = "NULL" if rng.random() < 0.2 else str(rng.randint(-5, 30))
        z = "NULL" if rng.random() < 0.1 else "'%s'" % rng.choice(words)
        s.ok("INSERT INTO t2(x,a,y,z) VALUES(%d,%s,%s,%s)" % (100 + i, a, y, z))


