    s.query("I", "SELECT count(*) FROM t1 LEFT JOIN t2 ON 1 = 0")
    s.query("I", "SELECT count(t2.x) FROM t1 LEFT JOIN t2 ON 1 = 0")
    s.query("II", "SELECT t1.a, s.m FROM t1 JOIN (SELECT a, max(y) AS m FROM t2 GROUP BY a) s ON s.a = t1.a",
            "rowsort")
