    s.query("II", "SELECT t1.a, t2.x FROM t1 JOIN t2 ON t1.a = t2.a WHERE t1.c IN (1, 3, 5, 7)", "rowsort")
    s.query("II", "SELECT t1.a, t2.x FROM t1 JOIN t2 ON t1.a = t2.a WHERE t1.b BETWEEN 0 AND 20", "rowsort")
    s.query("I", "SELECT DISTINCT t1.c FROM t1 JOIN t2 ON t1.a = t2.a", "rowsort")
