    s.query("II", "SELECT t1.a, t2.x FROM t2 JOIN t1 ON t2.a = t1.a", "rowsort", label="join-eq")
    s.query("II", "SELECT t1.a, t2.x FROM t1, t2 WHERE t2.a = t1.a", "rowsort", label="join-eq")
