def null_order(rng):
    s = Script("basics/null_order.test")
    seed_tables(s, rng)

    def pg(order_sql):
        """The same ORDER BY with PostgreSQL's NULL placement spelled out for SQLite."""
        parts, terms, depth, start = [], [], 0, 0
        for i, ch in enumerate(order_sql):
            depth += (ch == "(") - (ch == ")")
            if ch == "," and depth == 0:
                terms.append(order_sql[start:i])
                start = i + 1
        terms.append(order_sql[start:])
        for term in terms:
            term = term.strip()
            if "NULLS" in term:
                parts.append(term)
            elif term.upper().endswith(" DESC"):
                parts.append(term + " NULLS FIRST")
            else:
                parts.append(term + " NULLS LAST")
        return ", ".join(parts)

    def ordered(types, select, order, tail=""):
        s.query(types, "%s ORDER BY %s%s" % (select, order, tail),
                ask="%s ORDER BY %s%s" % (select, pg(order), tail))

    ordered("II", "SELECT a, b FROM t1", "b, a")
    ordered("II", "SELECT a, b FROM t1", "b DESC, a")
    ordered("II", "SELECT a, b FROM t1", "b ASC, a DESC")
    ordered("II", "SELECT a, b FROM t1", "b NULLS FIRST, a")
    ordered("II", "SELECT a, b FROM t1", "b NULLS LAST, a")
    ordered("II", "SELECT a, b FROM t1", "b DESC NULLS LAST, a")
    ordered("II", "SELECT a, b FROM t1", "b DESC NULLS FIRST, a")
    ordered("II", "SELECT a, c FROM t1", "c, b, a")
    ordered("II", "SELECT a, c FROM t1", "c DESC, b DESC, a")
    ordered("IT", "SELECT a, d FROM t1", "d, a")
    ordered("IT", "SELECT a, d FROM t1", "d DESC, a")
    ordered("IT", "SELECT a, d FROM t1", "d NULLS FIRST, a")
    ordered("II", "SELECT a, b FROM t1", "b, a", " LIMIT 5")
    ordered("II", "SELECT a, b FROM t1", "b DESC, a", " LIMIT 5")
    ordered("II", "SELECT a, b FROM t1", "b, a", " LIMIT 5 OFFSET 18")
    ordered("II", "SELECT a, b + c FROM t1", "b + c, a")
    ordered("II", "SELECT a, b + c AS s FROM t1", "s DESC, a")
    ordered("II", "SELECT a, coalesce(b, 0) FROM t1", "coalesce(b, 0), a")
    ordered("II", "SELECT a, b FROM t1 WHERE b IS NULL", "a")
    ordered("II", "SELECT a, b FROM t1 WHERE b IS NOT NULL", "b, a")
    ordered("II", "SELECT x, y FROM t2", "y, x")
    ordered("II", "SELECT x, y FROM t2", "y DESC, x DESC")
    ordered("II", "SELECT c, count(*) FROM t1 GROUP BY c", "c")
    ordered("II", "SELECT c, count(*) FROM t1 GROUP BY c", "c DESC")
    ordered("I", "SELECT DISTINCT c FROM t1", "c")
    ordered("I", "SELECT DISTINCT b FROM t1", "b DESC")
    ordered("II", "SELECT t1.a, t2.y FROM t1 LEFT JOIN t2 ON t1.a = t2.a", "t2.y, t1.a")
    ordered("II", "SELECT t1.a, t2.y FROM t1 LEFT JOIN t2 ON t1.a = t2.a", "t2.y DESC, t1.a")
    s.query("I", "SELECT count(*) FROM t1 WHERE b = NULL")
    s.query("I", "SELECT count(*) FROM t1 WHERE b <> NULL")
    s.query("I", "SELECT count(*) FROM t1 WHERE b IS NULL OR b > 0")
    s.query("I", "SELECT count(*) FROM t1 WHERE NOT (b > 0)")
    s.query("I", "SELECT count(*) FROM t1 WHERE b > 0 OR c > 0")
    s.query("I", "SELECT count(*) FROM t1 WHERE b > 0 AND c > 0")
    s.query("I", "SELECT count(*) FROM t1 WHERE b IN (1, 2, NULL)")
    s.query("I", "SELECT count(*) FROM t1 WHERE b NOT IN (1, 2, NULL)")
    s.query("I", "SELECT count(*) FROM t1 WHERE b NOT IN (1, 2)")
    s.query("I", "SELECT count(*) FROM t1 WHERE b BETWEEN NULL AND 10")
    s.query("II", "SELECT a, coalesce(b, c, -1) FROM t1", "rowsort")
    s.query("II", "SELECT a, nullif(c, 3) FROM t1", "rowsort")
    s.query("II", "SELECT a, CASE WHEN b IS NULL THEN -1 WHEN b > 10 THEN 1 ELSE 0 END FROM t1", "rowsort")
    s.query("II", "SELECT a, CASE b WHEN NULL THEN 1 ELSE 0 END FROM t1", "rowsort")
    s.query("II", "SELECT a, b + NULL FROM t1 WHERE a < 4", "rowsort")
    s.query("I", "SELECT NULL")
    s.query("T", "SELECT d FROM t1 WHERE d = ''", "valuesort")
    s.query("I", "SELECT count(*) FROM t1 WHERE d IS NULL")
    s.query("I", "SELECT count(*) FROM t1 WHERE d = ''")
    s.foreign("onlyif mysql", "query I nosort", "SELECT 1 FROM DUAL WHERE NULL <=> NULL", ["1"])
    s.foreign("onlyif sqlite", "statement ok", "PRAGMA case_sensitive_like = 0")
    return s.write()


